Standing obligations for this request:
1. Return exactly "invalid" for invalid inputs, never null or exceptions
2. Maintain original order for items that compare equal during sorting
3. Represent runs as either [level, count] lists or {"level": ..., "count": ...} objects
4. For schedule_cues, when ordering cues with same requested start time, use original input order (not longest duration first)
5. All functions returning JSON objects must include "version": 1

```python
def compact_cue(payload):
    if isinstance(payload, list):
        samples = payload
        tol = 0
    elif isinstance(payload, dict):
        if "samples" not in payload:
            return "invalid"
        samples = payload["samples"]
        tol = payload.get("tol", None)
        if tol is None or not isinstance(tol, int) or tol < 0:
            return "invalid"
    else:
        return "invalid"

    if not isinstance(samples, list):
        return "invalid"

    for sample in samples:
        if not isinstance(sample, int):
            return "invalid"

    if not samples:
        return []

    runs = []
    current_value = samples[0]
    current_count = 1

    for sample in samples[1:]:
        if abs(sample - current_value) <= tol:
            current_count += 1
        else:
            runs.append([current_value, current_count])
            current_value = sample
            current_count = 1

    runs.append([current_value, current_count])
    return runs
